// AUTO-GENERATED by Mosaic. Edits will be overwritten on next emit.
//
// mosaic_platform_effects.dart -- Mosaic's platform library for Flutter
// (UI87 §7, §7.7): the native file dialogs, and the one call the generated
// main.dart makes to install the library on its host.
//
// Everything else -- the contract, the file I/O and the router -- is in
// `mosaic_platform_effects_core.dart`, which is plain Dart so a headless test
// can run it on the Dart VM; this file adds the one part that needs the
// Flutter engine. It re-exports the core, so an app (or its own handler) that
// imports this file sees the whole library.
//
// The dialogs are `package:file_selector`'s, published by the Flutter team:
// the native panel on macOS, the common item dialog on Windows and GTK's file
// chooser on Linux. A sandboxed macOS build needs the
// `com.apple.security.files.user-selected.read-write` entitlement for them;
// without it the panel fails and the request is answered
// `failed { "the file dialog failed" }`. Generated projects carry it: the
// builder writes `macos/Runner/{DebugProfile,Release}.entitlements` before
// `flutter create` makes the runner, and `flutter create` keeps them.
//
// On Linux GTK's chooser does not ask before saving over a file (the plugin
// never turns that on), so this library asks itself, in a Material dialog on
// the app's root navigator; see `mosaicConfirmReplacing`. With no navigator to
// ask through, the save fails rather than replacing a file unasked.

import 'dart:io' show Platform;

import 'package:file_selector/file_selector.dart';
import 'package:flutter/material.dart';

import 'mosaic_host.dart';
import 'mosaic_platform_effects_core.dart';

export 'mosaic_platform_effects_core.dart';

/// `file_selector`'s dialogs. Returns full paths: the library reads and
/// writes through dart:io, so the bounded read and the temporary-then-move
/// save are the same code the headless test runs.
final class MosaicFileSelectorDialogs implements MosaicFileDialogs {
  const MosaicFileSelectorDialogs();

  @override
  Future<String?> chooseFileToOpen(List<String> extensions) async {
    final file = await openFile(acceptedTypeGroups: _groups(extensions));
    return file == null ? null : _localPath(file.path);
  }

  @override
  Future<String?> chooseFileToSave(
    String suggestedName,
    List<String> extensions,
  ) async {
    final location = await getSaveLocation(
      suggestedName: suggestedName,
      acceptedTypeGroups: _groups(extensions),
    );
    return mosaicConfirmReplacing(
      location == null ? null : _localPath(location.path),
      dialogAsked: !Platform.isLinux,
      ask: mosaicAskToReplace,
    );
  }

  /// One group of the accepted extensions, or none at all -- "any file",
  /// which is what no accepted type means (UI59 §3). An empty group would be
  /// refused on Linux, which needs a filter in every group it is given.
  static List<XTypeGroup> _groups(List<String> extensions) => extensions.isEmpty
      ? const <XTypeGroup>[]
      : <XTypeGroup>[XTypeGroup(label: 'Files', extensions: extensions)];

  /// A choice with no local path cannot be read or written through dart:io,
  /// so it throws -- failed, not a cancel nobody made.
  static String _localPath(String path) {
    if (path.isEmpty) {
      throw StateError('the chosen file has no local path');
    }
    return path;
  }
}

/// "Replace it?", asked in a Material dialog on the app's root navigator
/// (UI87 §7.7). True replaces; Cancel, or dismissing the question, keeps the
/// file. With no navigator to ask through it throws, which fails the save
/// ("the file dialog failed") rather than replacing a file nobody was asked
/// about.
///
/// The dialog is a `DialogRoute` pushed on the navigator, not `showDialog`:
/// `showDialog` goes through `showRawDialog`, which can open the dialog as a
/// window of its own and so reaches Flutter's desktop windowing code -- and
/// on macOS that code's FFI structs abort the AOT snapshotter ("Class with
/// illegal cid", Flutter 3.44 and 3.47), failing every release build of an
/// app that merely contains this library. The route is what `showDialog`
/// pushes when windowing is off, as it is by default.
Future<bool> mosaicAskToReplace(String fileName) async {
  final navigator = mosaicRootNavigator();
  if (navigator == null) {
    throw StateError('no window to ask whether to replace the file');
  }
  final context = navigator.context;
  final replace = await navigator.push<bool>(DialogRoute<bool>(
    context: context,
    // What showDialog passes: the themed barrier, and Tab kept inside the
    // question rather than reaching the page behind the barrier.
    barrierColor: DialogTheme.of(context).barrierColor ??
        Theme.of(context).dialogTheme.barrierColor ??
        Colors.black54,
    traversalEdgeBehavior: TraversalEdgeBehavior.closedLoop,
    builder: (context) => AlertDialog(
      title: Text('Replace "$fileName"?'),
      content: const Text(
        'A file with that name already exists. Replacing it overwrites '
        'its contents.',
      ),
      actions: <Widget>[
        TextButton(
          onPressed: () => Navigator.of(context).pop(false),
          child: const Text('Cancel'),
        ),
        TextButton(
          onPressed: () => Navigator.of(context).pop(true),
          child: const Text('Replace'),
        ),
      ],
    ),
  ));
  return replace ?? false;
}

/// The first navigator below the root of the widget tree -- the one the
/// generated `MaterialApp` builds -- found without asking `main.dart` for a
/// key, so a forked entry point works too. Null before the app is running.
NavigatorState? mosaicRootNavigator() {
  NavigatorState? found;
  void visit(Element element) {
    if (found != null) return;
    if (element is StatefulElement && element.state is NavigatorState) {
      found = element.state as NavigatorState;
      return;
    }
    element.visitChildren(visit);
  }

  WidgetsBinding.instance.rootElement?.visitChildren(visit);
  return found;
}

/// Install the platform library on [host], after the package's own
/// `[host_effects]` handler (the router wraps whatever handler is set when it
/// installs, so that order is what lets the app's kinds reach the app).
/// [appKinds] is that handler's `kinds`, or null when it declared none.
///
/// Called by the generated main.dart right after the host is assigned, on
/// every start: a retried start is a new host, and gets a new router.
void installMosaicPlatformEffects(
  MosaicHost host, {
  required List<String>? appKinds,
}) {
  installMosaicPlatformRouter(
    MosaicHostEffects(host),
    appKinds: appKinds,
    dialogs: const MosaicFileSelectorDialogs(),
  );
}
